165:     /** 提交付款；同步终态就地结算，受理中等待回调或查单。 */
166:     public void submitPayment(DrawdownOrder order) {
167:         try {
168:             SimulatorClient.PaymentSubmission sub = simulator.submitPayment(
169:                     order.getBizOrderNo(), order.getPayeeName(), order.getPayeeAccount(), order.getAmount());
170:             order.setExtSerialNo(sub.extSerialNo());
171:             order.setUpdatedAt(Ids.now());
172:             switch (sub.status()) {
173:                 case "SUCCESS" -> onPaymentResult(order, "SUCCESS");
174:                 case "REJECTED" -> onPaymentResult(order, "FAILED");
175:                 default -> order.setPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
176:             }
177:         } catch (Exception e) {
178:             // 提交失败保留 TO_SUBMIT，由补偿任务重试（模拟服务按 bizOrderNo 幂等）
179:             log.warn("付款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
180:         }
181:     }
182: 
183:     // -------------------------------------------------- 外部结果确认（回调与查单共用）
184: 
185:     /**
186:      * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
187:      */
188:     @Transactional
189:     public void onPaymentResult(DrawdownOrder order, String result) {
190:         if (order.terminal()) {
191:             return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
192:         }
193:         order.setUpdatedAt(Ids.now());
194:         if ("SUCCESS".equals(result)) {
195:             if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
196:                 return; // 幂等：成功已受理过
197:             }
198:             order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
199:             order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
200:             order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
201:             book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
202:         } else {
203:             if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
204:                 return;
205:             }
206:             order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
207:             order.setStatus(DrawdownOrder.Status.FAILED);
208:             limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
209:                     requiresGuarantee(order.getProductId()), order.getAmount());
210:         }
211:     }
212: 
213:     /**
214:      * 中台入账：调用 Fineract 放款登记 + 逐层预占转实占。
215:      * 幂等：入账前先查借据是否已 ACTIVE（重复回调/查单/重试不会重复放款）。
216:      */
217:     @Transactional
218:     public void book(DrawdownOrder order) {
219:         if (order.getBookingStatus() == DrawdownOrder.BookingStatus.BOOKED) {
220:             return;
221:         }
222:         try {
223:             if (fineract.isLoanActive(order.getLoanAccountNo())) {
224:                 log.info("借据已生效，跳过重复放款登记: {}", order.getLoanAccountNo());
225:             } else {
226:                 fineract.disburseLoan(order.getLoanAccountNo(), order.getAmount());
227:             }
228:             order.setBookingStatus(DrawdownOrder.BookingStatus.BOOKED);
229:             order.setBookedAmount(order.getAmount());
230:             order.setStatus(DrawdownOrder.Status.SUCCESS);
231:             order.setUpdatedAt(Ids.now());
232:             limitService.confirmOccupy(order.getCreditId(), order.getBizOrderNo(),
233:                     order.getLoanAccountNo(), order.getProductId(),
234:                     requiresGuarantee(order.getProductId()), order.getAmount());
235:         } catch (Exception e) {
236:             order.setBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED);
237:             order.setBookingRetryCount(order.getBookingRetryCount() + 1);
238:             order.setBookingLastError(e.getMessage());
239:             order.setUpdatedAt(Ids.now());
240:             log.warn("入账失败转补偿: {} retry={}", order.getBizOrderNo(), order.getBookingRetryCount());
241:         }
242:     }
243: 
244:     /** 查单收敛：补偿任务对 PROCESSING 超时的指令主动查单，结果走与回调相同的处理通道。 */
245:     @Transactional
246:     public void queryAndSettle(DrawdownOrder order) {
247:         SimulatorClient.ExternalStatus status = simulator.query("PAYMENT", order.getExtSerialNo());
248:         if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
249:             onPaymentResult(order, status.status());
250:         } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
251:             order.setPaymentStatus(DrawdownOrder.PaymentStatus.RESULT_UNCONFIRMED);
252:         }
253:     }
