259:         return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
260:                 "amount", order.getAmount(),
261:                 "payments", List.of(Map.of("extSerialNo", order.getExtSerialNo() == null ? "" : order.getExtSerialNo(),
262:                         "status", order.getPaymentStatus().name(), "amount", order.getAmount())),
263:                 "booking", Map.of("status", order.getBookingStatus().name(),
264:                         "loanAccountNo", order.getLoanAccountNo() == null ? "" : order.getLoanAccountNo(),
265:                         "retryCount", order.getBookingRetryCount()));
266:     }
